#!/usr/bin/env python3
"""
Descripciones de los nodos base (talentos, mecánicas, reactivas, legendarias y entrenamiento), estilo llano (v67).

Fuente única de las 300 claves node.aptitudes.<id>.desc que no generan gen_path_lang ni gen_evolved_lang:
- inglés y español se escriben en en_us/es_es (y en las seis variantes es_*) con --apply;
- portugués, francés y alemán los recoge node_catalog.TEXT (clave: el texto inglés) y gen_nodes_lang.

Estilo: primero qué hace, hablándole al jugador; condiciones con palabras; al final, «Rango 1 / 2 / 3: …» con las
cifras que cambian por rango. Sin coletillas. Las cifras de en/pt/fr/de deben coincidir (decimales con punto);
en español, coma decimal y espacio antes de «%».

Columnas: id¦inglés¦español¦portugués¦francés¦alemán. Se escribe «%» simple: las claves que ya usaban «%%»
(textos con formato) lo conservan al aplicar.

Uso: python3 tools/lang/base_desc.py --apply | --check
"""
import json
import os
import sys

from check_lang import LOCALES

ROOT = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..')
LANG = os.path.join(ROOT, 'src/main/resources/assets/aptitudes/lang')
SPANISH_VARIANTS = ('es_mx', 'es_ar', 'es_cl', 'es_ec', 'es_uy', 'es_ve')
COLUMNS = ('en_us', 'es_es') + LOCALES

DESC = {}


def rows(block):
    for row in block.strip().splitlines():
        node, *texts = row.split('¦')
        if len(texts) != len(COLUMNS) or node in DESC or any(not t.strip() for t in texts):
            raise ValueError(f'Descripción base inválida o duplicada: {node}')
        DESC[node] = dict(zip(COLUMNS, texts, strict=True))


