# ------------------------------------------------------------------------------------------------------ Legendarias
# «Siempre activo: …» (pasiva) y «Al activarla (tecla H): …» (activa); la ficha ya dice que es legendaria.
LEGEND_HEAD = {
    'en_us': ('Always on: ', ' When activated (H key): '), 'es_es': ('Siempre activo: ', ' Al activarla (tecla H): '),
    'pt_br': ('Sempre ativo: ', ' Ao ativar (tecla H): '), 'fr_fr': ('Toujours actif : ', ' À l’activation (touche H) : '),
    'de_de': ('Immer aktiv: ', ' Bei Aktivierung (Taste H): '),
}
LEGEND_ONLY_ACTIVE = {'en_us': 'When activated (H key): ', 'es_es': 'Al activarla (tecla H): ',
                      'pt_br': 'Ao ativar (tecla H): ', 'fr_fr': 'À l’activation (touche H) : ',
                      'de_de': 'Bei Aktivierung (Taste H): '}


def legends(block):
    """Filas id¦pasiva×5¦activa×5 (la pasiva puede ir vacía)."""
    for row in block.strip().splitlines():
        node, *texts = row.split('¦')
        if len(texts) != 2 * len(COLUMNS) or node in DESC:
            raise ValueError(f'Legendaria inválida o duplicada: {node}')
        passive, active = texts[:len(COLUMNS)], texts[len(COLUMNS):]
        DESC[node] = {lang: (LEGEND_HEAD[lang][0] + p + LEGEND_HEAD[lang][1] + a) if p else LEGEND_ONLY_ACTIVE[lang] + a
                      for lang, p, a in zip(COLUMNS, passive, active, strict=True)}


