# ------------------------------------------------------------------------------------------------------- Aplicación
def localized(node, lang, escaped):
    text = DESC[node][lang]
    return text.replace('%', '%%') if escaped else text


def apply(check=False):
    """Escribe las descripciones en en_us y es_es (y copia es_es a sus variantes). Devuelve 1 si algo cambia en --check."""
    path = {lang: os.path.join(LANG, f'{lang}.json') for lang in ('en_us', 'es_es')}
    data = {lang: json.load(open(p, encoding='utf-8')) for lang, p in path.items()}
    keys = {f'node.aptitudes.{node}.desc' for node in DESC}
    missing = keys - data['en_us'].keys()
    if missing:
        raise ValueError(f'Claves que no existen en en_us: {sorted(missing)}')
    changed = False
    for lang in path:
        for node in DESC:
            key = f'node.aptitudes.{node}.desc'
            escaped = '%%' in data[lang][key]
            value = localized(node, lang, escaped)
            changed |= data[lang][key] != value
            data[lang][key] = value
        if not check:
            rendered = json.dumps(data[lang], ensure_ascii=False, indent=2) + '\n'
            targets = [lang] + (list(SPANISH_VARIANTS) if lang == 'es_es' else [])
            for target in targets:
                with open(os.path.join(LANG, f'{target}.json'), 'w', encoding='utf-8', newline='\n') as out:
                    out.write(rendered)
    return int(check and changed)


def catalog():
    """{texto inglés: {pt_br, fr_fr, de_de}} para node_catalog; un texto repetido debe traducirse igual."""
    reference = json.load(open(os.path.join(LANG, 'en_us.json'), encoding='utf-8'))
    out = {}
    for node, texts in DESC.items():
        escaped = '%%' in reference.get(f'node.aptitudes.{node}.desc', '')
        source = localized(node, 'en_us', escaped)
        value = {lang: localized(node, lang, escaped) for lang in LOCALES}
        if out.setdefault(source, value) != value:
            raise ValueError(f'Texto repetido con traducciones distintas: {source}')
    return out


if __name__ == '__main__':
    if sys.argv[1:] == ['--apply']:
        raise SystemExit(apply())
    if sys.argv[1:] == ['--check']:
        status = apply(check=True)
        print('desactualizado' if status else 'descripciones base comprobadas')
        raise SystemExit(status)
    print(__doc__)
    raise SystemExit(2)
